import { env } from "../config/env.js";

/**
 * Calculates user's AI requests (advisories + chat messages) within the last 24 hours.
 */
export async function checkUserDailyQuota(supabase, userId) {
  const since = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString();

  // Count advisories generated by the user in last 24h
  const { count: advisoriesCount, error: advErr } = await supabase
    .from("advisories")
    .select("id", { count: "exact", head: true })
    .eq("user_id", userId)
    .gte("created_at", since);

  if (advErr) {
    console.error("Error querying advisories quota:", advErr);
    // If table count fails, allow request but log warning
    return { allowed: true, current: 0, limit: env.AI_DAILY_LIMIT_PER_USER };
  }

  // Count messages sent by the user in last 24h
  const { count: messagesCount, error: msgErr } = await supabase
    .from("advisory_messages")
    .select("id", { count: "exact", head: true })
    .eq("user_id", userId)
    .eq("role", "user")
    .gte("created_at", since);

  if (msgErr) {
    console.error("Error querying messages quota:", msgErr);
  }

  const totalUsed = (advisoriesCount || 0) + (messagesCount || 0);
  const allowed = totalUsed < env.AI_DAILY_LIMIT_PER_USER;

  return {
    allowed,
    current: totalUsed,
    limit: env.AI_DAILY_LIMIT_PER_USER,
    remaining: Math.max(0, env.AI_DAILY_LIMIT_PER_USER - totalUsed)
  };
}
